{"edits":[{"old":"FUNCTION_BLOCK FB
VAR_INPUT
    enable    : BOOL;
    rawValue  : REAL;
END_VAR
VAR_OUTPUT
    filteredValue : REAL := 0.0;
    windowFull    : BOOL := FALSE;
    sampleCount   : INT  := 0;
END_VAR
VAR
    ringBuffer   : ARRAY[1..8] OF REAL;
    writeIndex   : INT  := 0;
    prev_rawValue : REAL := 0.0;
    tmp_i        : INT;
    tmp_sum      : REAL;
END_VAR

// Same-scan priority: enable falling edge clears state before any other logic
IF NOT enable THEN
    sampleCount := 0;
    writeIndex  := 0;
    windowFull  := FALSE;
    // filteredValue intentionally NOT written -> retains last value (PUB035)
ELSE
    // enable is TRUE: push sample, compute mean
    writeIndex := ((writeIndex + 1) MOD 8) + 1; // circular 1..8
    ringBuffer[writeIndex] := rawValue;

    IF sampleCount < 8 THEN
        sampleCount := sampleCount + 1;
    END_IF;

    windowFull := (sampleCount = 8); // latch until disable

    // Compute arithmetic mean over actual valid samples only
    tmp_sum := 0.0;
    FOR tmp_i := 1 TO sampleCount DO
        tmp_sum := tmp_sum + ringBuffer[tmp_i];
    END_FOR;
    filteredValue := tmp_sum / TO_REAL(sampleCount);

    prev_rawValue := rawValue;
END_IF;

// Propagate outputs (already assigned in branches above)
END_FUNCTION_BLOCK", "new":"FUNCTION_BLOCK FB
VAR_INPUT
    enable   : BOOL;
    rawValue : REAL;
END_VAR
VAR_OUTPUT
    filteredValue : REAL := 0.0;
    windowFull    : BOOL := FALSE;
    sampleCount   : INT  := 0;
END_VAR
VAR
    ringBuffer    : ARRAY[1..8] OF REAL;
    writeIndex    : INT  := 0;
    prev_rawValue : REAL := 0.0;
    tmp_i         : INT;
    tmp_sum       : REAL;
END_VAR

// Same-scan priority: enable falling edge clears state before any other logic
IF NOT enable THEN
    sampleCount := 0;
    writeIndex  := 0;
    windowFull  := FALSE;
    // filteredValue intentionally NOT written -> retains last value (PUB035)
ELSE
    // enable is TRUE: push sample, compute mean
    IF sampleCount < 8 THEN
        sampleCount := sampleCount + 1;
        writeIndex  := sampleCount;
    ELSE
        // Buffer full: FIFO eviction, rotate indices 1..7 forward
        FOR tmp_i := 1 TO 7 DO
            ringBuffer[tmp_i] := ringBuffer[tmp_i + 1];
        END_FOR;
        ringBuffer[8] := rawValue;
    END_IF;

    IF sampleCount < 8 THEN
        ringBuffer[sampleCount] := rawValue;
    END_IF;

    windowFull := (sampleCount = 8); // latch until disable

    // Compute arithmetic mean over actual valid samples only
    tmp_sum := 0.0;
    FOR tmp_i := 1 TO sampleCount DO
        tmp_sum := tmp_sum + ringBuffer[tmp_i];
    END_FOR;
    filteredValue := tmp_sum / TO_REAL(sampleCount);

    prev_rawValue := rawValue;
END_IF;

END_FUNCTION_BLOCK"}]}
